                temp = a[i]
                a[i] = a[j]
                a[j] = temp
                if all(a[k] <= a[k + 1] for k in range(n - 1)):
                    return len(inversions), inversions
                else:
                    # Swap back if it doesn't help
                    a[i] = temp
                    a[j] = temp

